def find_output(input_grid):
    output_grid = []
    current_row = []
    current_value = None

    for row in input_grid:
        if row == input_grid[0]:
            current_value = row[0]
            current_row.append(current_value)
        else:
            if row[0] != input_grid[input_grid.index(row) - 1][0]:
                current_value = row[0]
                current_row.append(current_value)

        if input_grid.index(row) == len(input_grid) - 1:
            output_grid.append(current_row)
        else:
            next_row = input_grid[input_grid.index(row) + 1]
            if next_row[0] != row[0]:
                output_grid.append(current_row)
                current_row = []

    # clean and update current_row for every row in input_grid
    cleaned_output_grid = []
