                current_value = input_grid[i][0]
                current_row.append(current_value)
        if i == len(input_grid) - 1:
            cleaned_output_grid.append(current_row)

    # check every row for change in value and update output_grid
    for col_index in range(len(input_grid[0])):
        current_value = input_grid[0][col_index]
        for row_index in range(len(input_grid)):
            if input_grid[row_index][col_index] != current_value:
