                cleaned_output_grid[col_index].append(current_value)
                current_value = input_grid[row_index][col_index]
        if col_index >= len(cleaned_output_grid):
            cleaned_output_grid.append([input_grid[0][col_index]])

    output_grid = list(map(list, zip(*cleaned_output_grid)))
    return output_grid


